insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('6b177655-a819-4fdf-b89d-4dd4b3c84c70', '004df4d5-e631-478e-87d2-8ce333c3b0ad', $$schadeverzekeringen hebben hun oorsprong in de scheepvaart; risico-opslag op de transportprijs$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-context1.png$$,
   $$Schadeverzekeringen hebben hun oorsprong in de scheepvaart. De Romeinen dreven handel met verre gebieden, waardoor er extra risico was van schade, bijvoorbeeld door zeerovers. Daarom werd de transportprijs verhoogd met een risico- opslag. Tegenwoordig is er een aparte verzekeringsmarkt waar schaderisico’s worden ondergebracht bij schadeverzekeraars.$$, 'inline'),
  ('cdb2d960-05ad-4ef8-b851-a4a3b634b255', '004df4d5-e631-478e-87d2-8ce333c3b0ad', $$een econoom presenteert de factoren die de vraag naar schadepolissen beïnvloeden in een schema (zie bron 1)$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-context2.png$$,
   $$Een econoom heeft onderzoek gedaan naar de vraag naar schade- polissen en presenteert de bevindingen in een schema (zie bron 1).$$, 'inline'),
  ('62066169-b532-42d3-9294-e44348934732', '004df4d5-e631-478e-87d2-8ce333c3b0ad', $$redenering van de econoom bij pijl 3: het schadelasteffect (invulzinnen)$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-context3.png$$,
   $$In zijn rapport geeft de econoom de volgende redenering bij pijl 3 van bron 1. “Om winst te maximaliseren zou je verwachten dat verzekeraars de schadelast (uit te keren schade per gebeurtenis) proberen te minimaliseren. Toch kan een hogere schadelast zelfs tot hogere winst leiden, en dat komt door het zogenaamde ‘schadelasteffect’. Een voorbeeld: Als consumenten weten dat autoruitschade gemiddeld 200 euro kost, dan zal de vraag naar ruitschadeverzekeringen relatief laag zijn.
− Stel nu dat de reparaties zo veel duurder zijn geworden dat de schadelast 700 euro bedraagt. Door een toename van de schadelast nemen de marginale kosten van verzekeringspolissen …(1)…, verschuift de aanbodlijn van de polis …(2)…, en zal de verzekeraar de premie …(3)… .
− Door een verschuiving …(4)…de vraaglijn zal het aantal afgesloten polissen …(5)….
− Maar door het verhoogde risico voor de consument (het schadelasteffect) verschuift de vraaglijn van deze verzekeringspolis …(6)…. Dit schadelasteffect draagt bij aan een …(7)… verband tussen de schadelast en het aantal afgesloten polissen. Daardoor kan uiteindelijk de winst zelfs toenemen.”$$, 'inline'),
  ('6b07dcb9-9f1b-431a-895b-2f4d2371d289', '004df4d5-e631-478e-87d2-8ce333c3b0ad', $$bron 1: factoren die de collectieve vraag naar schadepolissen beïnvloeden (pijlenschema)$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-context4.png$$,
   $$bron 1 factoren die de collectieve vraag naar schadepolissen beïnvloeden
schema: hoogte van de premie → pijl 1 (−) → vraag naar polissen; kans op schade → pijl 2 (+) → vraag naar polissen; risico-aversie → pijl 4 (....) → vraag naar polissen; schadelast → pijl 3 (....) → vraag naar polissen
Toelichting: Elke pijl staat voor een oorzaak-gevolgverband. Een − staat voor een negatief verband en een + voor een positief verband.$$, 'inline'),
  ('a6a7ae3f-d859-4d56-a7fb-8e3d3e5c0633', '004df4d5-e631-478e-87d2-8ce333c3b0ad', $$bron 2: vier grafieken van de verandering in de vraaglijn bij een toename van de kans op schade$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-context5.png$$,
   $$bron 2 verandering in de vraaglijn bij een toename van de kans op schade
vier grafieken (premie in euro’s tegen aantal polissen Q), elk met een oorspronkelijke vraaglijn en de vraag bij toename van de kans op schade:
1: de vraaglijn verschuift evenwijdig naar rechts
2: de vraaglijn verschuift evenwijdig naar links
3: verschuiving langs de oorspronkelijke vraaglijn naar rechtsonder
4: verschuiving langs de oorspronkelijke vraaglijn naar linksboven$$, 'inline'),
  ('aed04d7e-17f9-41ee-aa73-6a28bd4bb8a8', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', $$spaargedrag van Nederlandse huishoudens: oplopende spaartegoeden en meer roodstand (CBS-cijfers)$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-context1.png$$,
   $$Het spaargedrag van Nederlandse huishoudens liet tot circa 2013 twee tegengestelde ontwikkelingen zien. Aan de ene kant liepen de spaartegoeden flink op omdat de huishoudens hun koopkracht in de toekomst veilig willen stellen. Aan de andere kant maakten Nederlanders meer gebruik van consumptief krediet zoals roodstaan op de betaalrekening en kopen op afbetaling. Bij het Centraal Bureau voor de Statistiek (CBS) zijn cijfers beschikbaar over schuld in de roodstand onder volwassenen, dat wil zeggen onder volwassenen met een negatief saldo op de betaalrekening aan het eind van een maand. Uit deze cijfers blijkt dat de gemiddelde schuld in de roodstand eind december 2012 de hoogte had bereikt van 3.800 euro. De roodstand was daarmee hoger dan het modale netto-inkomen per maand. De totale schuld in de roodstand was gestegen van 7,8 miljard euro eind december 2007 naar 10,1 miljard euro eind december 2012. In de jaren na 2012 is de schuld in de roodstand geleidelijk weer gezakt.$$, 'inline'),
  ('95ac0725-422c-47bc-af02-efc74a0628ca', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', $$een onderzoeker beweert dat meer dan een kwart van de volwassenen rood stond$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-context2.png$$,
   $$Een onderzoeker beweert dat meer dan een kwart van de tien miljoen volwassenen eind december 2012 rood stond op de betaalrekening.$$, 'inline'),
  ('f492e54e-4703-4886-bce4-23ec50a6c838', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', $$de spaarparadox: Nederlanders vulden hun spaarpot zonder te sparen$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-context3.png$$,
   $$In Nederland was sprake van een ‘spaarparadox’: Nederlanders vulden hun spaarpot zonder te ‘sparen’. Oftewel: Nederlanders gaven meer geld uit dan ze aan inkomen ontvingen, maar toch namen de spaartegoeden elk jaar toe.$$, 'inline'),
  ('9c7f1326-08e5-41f2-b93d-1b85cd61ed83', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', $$DNB: actief sparen en passief sparen$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-context4.png$$,
   $$Om dit te kunnen verklaren moeten we kijken naar de manier waarop de Nederlanders sparen. De Nederlandse Bank (DNB) stelt dat Nederlandse huishoudens op twee verschillende manieren sparen.
− Actief sparen: huishoudens consumeren hun inkomen niet volledig en bewaren een deel van hun inkomen voor later.
− Passief sparen: het vermogen neemt toe door waardevermeerdering van beleggingen in financiële producten, exclusief bijschrijven van rente en dividend.$$, 'inline'),
  ('13139fcc-6e3b-4eaf-935e-8d76e57979e8', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', $$DNB-onderzoek: samenhang tussen actief en passief sparen verklaart de spaarparadox$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-context5.png$$,
   $$Uit een onderzoek van DNB blijkt dat actief en passief sparen met elkaar samenhangen: bij iedere waardestijging van het vermogen met € 100, daalt het actief sparen met € 8. Hiermee hebben de onderzoekers de verklaring gevonden voor de Nederlandse spaarparadox. De onderzoeker zegt: “De verklaring van de Nederlandse spaarparadox zit in de sterke waardestijging van beleggingen, het spaargedrag van huishoudens in het kader van de levensloopplanning, het onderscheid tussen actief en passief sparen, en de samenhang tussen actief en passief sparen.”$$, 'inline'),
  ('a86fb107-5d4e-43b4-8579-573390f87509', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', $$uit een krant (2019): reisbureau IFLAS failliet door concurrentie van online reisbureaus$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-context1.png$$,
   $$Uit een krant, 2019: IFLAS, een reisbureau met reiswinkels in een aantal Nederlandse steden, is failliet verklaard. Econoom Jessica van Min legt uit dat de gemiddelde winst van reisbureaus met een fysieke winkel is gedaald als gevolg van de toegenomen concurrentie met de online reisbureaus: op een all- inclusive reis naar Turkije wordt hooguit een tientje verdiend. Hierdoor zijn reisbureaus met een fysieke winkel kwetsbaar in hun voortbestaan.$$, 'inline'),
  ('907260bd-98e5-4a92-854f-75d441f5a117', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', $$steeds meer online reisbureaus zijn tot de markt toegetreden$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-context2.png$$,
   $$In voorgaande jaren zijn steeds meer online reisbureaus toegetreden tot de markt, doordat ze aantrekkelijke winsten konden behalen.$$, 'inline'),
  ('e0e313a2-d272-4ca1-a9af-423f435fe7a5', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', $$Van Min: alleen toekomst voor online reisbureaus; twee uitspraken over prijselasticiteiten (zie bron 1)$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-context3.png$$,
   $$Van Min vervolgt in het krantenbericht: “Zelfs een bekend reisbureau als IFLAS redt het dus niet. Er lijkt alleen nog toekomst te zijn voor online reisbureaus die reizen verkopen met een lage gemiddelde winst in combinatie met een grote afzet.” Van Min bestudeert de prijselasticiteiten voor binnenlandse en buitenlandse reizen (zie bron 1), en leidt daaruit af:
1 dat van buitenlandse reizen meer afzetgroei te verwachten is dan van binnenlandse reizen bij dezelfde procentuele prijsverlaging
2 en dat reisbureaus die zich toeleggen op buitenlandse reizen hun omzet zullen zien stijgen ondanks de lagere prijzen, terwijl reisbureaus die zich toeleggen op binnenlandse reizen hun omzet zullen zien dalen als gevolg van de lagere prijzen.$$, 'inline'),
  ('c1004188-685f-4d14-8637-33e00bc9985a', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', $$bron 1: economische kengetallen voor binnenlandse en buitenlandse reizen$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-context4.png$$,
   $$bron 1 economische kengetallen voor binnenlandse en buitenlandse reizen
binnenlandse reizen: aantal reizen (x 1 miljoen) vorig jaar 13,8 | dit jaar 14,1; prijsindexcijfer vorig jaar 100 | dit jaar 96,1; prijselasticiteit dit jaar −0,56
buitenlandse reizen: aantal reizen (x 1 miljoen) vorig jaar 12,9 | dit jaar 13,3; prijsindexcijfer vorig jaar 100 | dit jaar 99,3; prijselasticiteit dit jaar −4,4$$, 'inline'),
  ('070b289f-45e4-47c5-ba9d-91df1cf40e8c', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', $$studentenkamers in Amsterdam zijn het duurst van Nederland; huisbazen laten studenten tegen elkaar opbieden$$,
   $$economie-havo-2022-ii-kamertje-verhuren-context1.png$$,
   $$Uit onderzoek blijkt dat studentenkamers in Amsterdam het duurst van Nederland zijn. Kamers in Amsterdam zijn zo gewild, dat huisbazen studenten zelfs tegen elkaar op laten bieden. Degene die het hoogste biedt krijgt de kamer.$$, 'inline'),
  ('56764ada-1948-41ac-8079-7cd866372b4c', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', $$de gemeente Amsterdam vindt de hoge huren ongewenst; de markt gedraagt zich als volkomen concurrentie$$,
   $$economie-havo-2022-ii-kamertje-verhuren-context2.png$$,
   $$De gemeente Amsterdam vindt de hoge huren ongewenst. De gemeente vraagt een adviesbureau te onderzoeken welke maatregelen hiertegen genomen kunnen worden. Het adviesbureau constateert dat de huren op de meest gewilde locaties weliswaar hoog zijn, maar dat vraag en aanbod op de markt in evenwicht zijn. Er zijn geen toetredingsbarrières geconstateerd en de aanbieders hebben een verwaarloosbaar kleine invloed op de prijs. Daarom gaan ze er in de analyse van uit dat de markt voor studentenkamers zich min of meer gedraagt als een markt van volkomen concurrentie.$$, 'inline'),
  ('cda28dea-00a7-49ee-a05c-b35bd27d0e2b', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', $$drie opties van het adviesbureau om de hoge huren tegen te gaan$$,
   $$economie-havo-2022-ii-kamertje-verhuren-context3.png$$,
   $$Het bureau stelt in een rapport de volgende drie opties voor om de hoge huren tegen te gaan:
1 De gemeente gaat zelf studentenkamers bouwen en verhuren.
2 De gemeente grijpt in op deze markt middels prijsregulering
3 De gemeente grijpt niet in omdat studenten steeds langer bij hun ouders willen blijven wonen en de huurprijzen van studentenkamers daardoor vanzelf zullen dalen.$$, 'inline'),
  ('7cba3c84-b5e3-4d98-a260-5ff0c64dca60', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', $$bron 1: vier figuren van de markt voor studentenkamers in Amsterdam$$,
   $$economie-havo-2022-ii-kamertje-verhuren-context4.png$$,
   $$bron 1 markt studentenkamers Amsterdam
vier figuren (huurprijs in € tegen aantal studentenkamers) met vraaglijn Qv en aanbodlijn Qa:
1: nieuwe aanbodlijn Qa’ evenwijdig boven/links van Qa
2: nieuwe vraaglijn Qv’ evenwijdig links van Qv
3: nieuwe aanbodlijn Qa’ evenwijdig onder/rechts van Qa
4: nieuwe vraaglijn Qv’ evenwijdig rechts van Qv
Legenda: Qa = aangeboden hoeveelheid in de uitgangssituatie; Qa’ = aangeboden hoeveelheid na maatregelen; Qv = gevraagde hoeveelheid in de uitgangssituatie; Qv’ = gevraagde hoeveelheid na maatregelen$$, 'inline'),
  ('7b5aa95c-608a-44cd-b7a7-c69bfa5e2a51', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$uit een krant (januari 2017): de koers van de IJslandse kroon (ISK) daalde en steeg weer (zie bron 1)$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context1.png$$,
   $$Uit een krant van januari 2017: IJsland is vanaf 2007 hard geraakt door de economische crisis. In het begin van de crisis daalde de koers van de nationale munt, de IJslandse kroon (ISK), ten opzichte van de euro. Vanaf 2009 steeg de koers van de ISK in euro’s (zie bron 1).$$, 'inline'),
  ('77494665-9927-48ea-92de-3d723697a1ee', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$een Nederlandse vishandelaar importeert gerookte zalm uit IJsland tegen € 20,00 per kilo in 2007$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context2.png$$,
   $$De export van IJsland naar Nederland betreft vooral vis. De Nederlandse vishandelaar Dirk Diekstra importeert gerookte zalm uit IJsland. Hij kijkt terug naar de periode tussen 2007 en 2009 waarin de koers van de ISK in euro’s sterk daalde. Hij zegt tegen zijn compagnon: “De koersdaling tussen 2007 en 2009 heeft onze handel beïnvloed. De gemiddelde inkoopprijs in 2007 van omgerekend € 20,00 per kilo gerookte zalm is in 2009 veranderd.”$$, 'inline'),
  ('5d9c414c-5c69-4eed-95f5-9a099c145d43', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$de IJslandse minister wil een vaste wisselkoers tussen de ISK en de euro$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context3.png$$,
   $$Vervolg van het krantenbericht: Na 2009 groeide de IJslandse economie weer. Nu wil de IJslandse minister van Financiën de export bevorderen door het systeem van flexibele wisselkoersen te veranderen naar een systeem van vaste wisselkoersen: er komt dan een vaste koersverhouding tussen de IJslandse kroon en de euro.$$, 'inline'),
  ('46b109ba-cafe-4943-aab9-a8b526885d75', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$positieve en negatieve twitterberichten over het koppelen van de ISK aan de euro$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context4.png$$,
   $$Onmiddellijk na de bekendmaking van het voornemen van de IJslandse minister om de ISK te koppelen aan de euro verschenen er zowel positieve als negatieve twitterberichten. Een bericht dat verscheen:$$, 'inline'),
  ('405de7de-78dc-437a-82f7-22dbc2e969af', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$twitterbericht: een vaste wisselkoers maakt effectief conjunctuurbeleid onmogelijk$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context5.png$$,
   $$Twitterbericht “Weet onze minister wel welk gevaar wij lopen? Realiseert men zich daar in de hoofdstad Reykjavik wel dat het aanhouden van een vaste wisselkoers effectief conjunctuurbeleid door de overheid onmogelijk maakt?”$$, 'inline'),
  ('24146bd8-2733-4ed0-acc5-7c91ea2ea915', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$redenering van een IJslandse econoom over stimulering van de bestedingen (invulzinnen)$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context6.png$$,
   $$Een IJslandse econoom bevestigt dat de overheid inderdaad geen effectief conjunctuurbeleid kan voeren door de koppeling met de euro. De econoom begint zijn redenering als volgt: “Stel dat de overheid de bestedingen (O) zou stimuleren, dan …(1)… het Nationaal Inkomen (Y). Hierdoor …(2)… de bestedingen (C) en neemt de …(3)… toe. Hierdoor stijgt …(4)… de munt ISK. Hierdoor dreigt de wisselkoers van de munt ISK in euro’s te dalen, maar dat mag niet omdat juist gekozen was voor een vaste wisselkoers.”$$, 'inline'),
  ('c02b0844-158c-45fe-9915-780b099788c5', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$vervolg van de redenering: de Centrale Bank verdedigt de vaste wisselkoers (invulzinnen)$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context7.png$$,
   $$De IJslandse econoom vervolgt de redenering: “De Centrale Bank zal de daling van de koers van de munt ISK in euro’s tegengaan om de vaste wisselkoers te handhaven. Om te voorkomen dat de koers daalt, ...(1)… de Centrale Bank de rente zodat de kapitaalinvoer stijgt. Hierdoor stijgt …(2)… de ISK. Als gevolg van de renteaanpassing door de Centrale Bank …(3)… de bestedingen van consumenten en …(4)… de besparingen. Dit betekent dat het conjunctuurbeleid van de overheid teniet wordt gedaan.”$$, 'inline'),
  ('90ee81cc-eb82-43be-80be-eecfc9f33720', '268c23a0-86ef-48d4-9625-b9cd9c2765f2', $$bron 1: koers van de euro in IJslandse kroon (jaargemiddelde) 2007-2017$$,
   $$economie-havo-2022-ii-ijsland-lonkt-naar-euro-context8.png$$,
   $$bron 1 koers euro in IJslandse kroon (jaargemiddelde)
lijngrafiek koers euro (in ISK): 2007 80 | 2008 150 | 2009 180 | 2010 151 | 2011 155 | 2012 148 | 2013 158 | 2014 150 | 2015 142 | 2016 120 | 2017 128$$, 'inline'),
  ('9016e9e5-2001-4ee1-8bfe-85e6a731aec4', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$uit een bericht van het CBS: inkomensdaling tijdens de crisis 2008-2012; inkomen zelfstandigen afhankelijk van de conjunctuur$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context1.png$$,
   $$Uit een bericht van het Centraal Bureau voor de Statistiek (CBS): De economische crisis van 2008 ‒ 2012 heeft geleid tot een inkomensdaling voor huishoudens. Deze inkomensdaling was niet gelijk verdeeld over de verschillende inkomensgroepen. Het nominale inkomen van werknemers veranderde bijna niet, terwijl het nominale inkomen van zelfstandigen1) wel sterk afhankelijk bleek van de conjunctuur. De nominale uitkeringen zijn gekoppeld aan de cao-lonen.
noot 1 Een zelfstandige is een persoon die arbeid verricht voor eigen rekening of risico in een eigen bedrijf.$$, 'inline'),
  ('749c8e26-a90b-476e-a3da-347e566c3702', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$de inkomensverschillen werden kleiner tijdens de crisis; verhouding hoogste/laagste 20% van 2,8 naar 2,5 (zie bron 1)$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context2.png$$,
   $$De inkomensverschillen in Nederland zijn kleiner geworden tijdens de economische crisis van 2008 − 2012. In bron 1 staan de Lorenzcurven van secundaire inkomens van vóór en van ná de crisis. Volgens het CBS verdiende de 20 procent van de personen met de hoogste netto-inkomens in 2008 (aan het begin van de economische crisis) 2,8 keer zo veel als de groep van de 20 procent van de personen met de laagste netto-inkomens. In 2012 (aan het eind van de economische crisis) was dit 2,5 keer zo veel.$$, 'inline'),
  ('8e0a1f5a-0ce8-45a8-bf74-81df377e164b', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$het CBS: de groep met de 20 procent hoogste inkomens bevat relatief veel zelfstandigen$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context3.png$$,
   $$Het CBS heeft geconstateerd dat de groep met de 20 procent hoogste inkomens relatief veel zelfstandigen bevat.$$, 'inline'),
  ('168ad2e4-594c-4d98-9377-7313df30998b', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$Nederland kent een progressief belastingsysteem$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context4.png$$,
   $$Nederland kent een progressief belastingsysteem.$$, 'inline'),
  ('f4176c21-6188-41f0-a1cd-8cfe5282dcd5', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$de overheid kan belastinginkomsten gebruiken om de welvaart in ruime zin te verhogen$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context5.png$$,
   $$De overheid kan belastinginkomsten gebruiken om de welvaart in ruime zin te verhogen.$$, 'inline'),
  ('54ffa7ea-616d-44d4-982d-9f272a3fdb51', 'ccbefea6-302e-4e70-a199-bff24687e5c3', $$bron 1: Lorenzcurven van de secundaire inkomensverdeling in 2008 en 2012$$,
   $$economie-havo-2022-ii-crisis-en-inkomen-context6.png$$,
   $$bron 1 Lorenzcurve van de secundaire (netto-inkomens) inkomensverdeling
cumulatief % inkomen tegen cumulatief % personen, met rechte lijn (gelijkheidslijn) en de Lorenzcurven van 2012 en 2008
aangegeven punten 2012: 20% → 12 | 40% → 29 | 60% → 48 | 80% → 70 | 100% → 100
aangegeven punten 2008: 20% → 12 | 40% → 27 | 60% → 45 | 80% → 66 | 100% → 100$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('61aa3c9c-3a3b-468f-871d-8b6e20e6ae52', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 1,
   '[{"domain": "Markt", "subdomain": "Consumentengedrag"}]'::jsonb,
   '["complementaire goederen", "substitutiegoederen", "complementaire diensten", "transport"]'::jsonb,
   $$Bepalen of transport en schadeverzekeringen complementaire of substitutiediensten zijn.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag1.png$$, $$1p 1 Zijn transport en schadeverzekeringen substitutiediensten of complementaire diensten? Licht je keuze toe.$$, array['6b177655-a819-4fdf-b89d-4dd4b3c84c70']::uuid[]),
  ('d983a0ee-aa18-4930-adcf-aa53bc21a3f7', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 2,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop, nationaal inkomen en welvaart"}]'::jsonb,
   '["bruto binnenlands product", "toegevoegde waarde", "dienstverlening", "productiemethode"]'::jsonb,
   $$Uitleggen dat schadeverzekeraars met hun toegevoegde waarde bijdragen aan het bbp.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag2.png$$, $$2p 2 Leg uit dat de markt van schadeverzekeringen een bijdrage levert aan het bruto binnenlands product.$$, array['6b177655-a819-4fdf-b89d-4dd4b3c84c70']::uuid[]),
  ('a405774a-1546-4a71-a8d3-d90d17e4a914', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 3,
   '[{"domain": "Risico en informatie", "subdomain": "Asymmetrische informatie"}]'::jsonb,
   '["asymmetrische informatie", "averechtse selectie", "moral hazard", "premieopslag"]'::jsonb,
   $$Invullen hoe asymmetrische informatie via averechtse selectie en moral hazard tot een premieopslag leidt.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag3.png$$, $$2p 3 Maak de onderstaande redenering economisch correct.
− Verzekeraars kennen de persoonlijke risico’s van hun klanten minder goed dan de klanten die zelf kennen, oftewel, de verzekeraars hebben te maken met …(1)…. Een gevolg daarvan is dat de verzekeraars worden geconfronteerd met twee economische verschijnselen.
− Het eerste is…(2)…, wat betekent dat alleen consumenten die verwachten dat het schadebedrag minimaal gelijk is aan de te betalen premie zich laten verzekeren.
− Het tweede is …(3)… wat betekent dat verzekerde consumenten roekelozer met hun bezittingen omgaan.
− Beide verschijnselen kunnen tot gevolg hebben dat het …(4)… schadebedrag hoger is dan het …(5)…schadebedrag op basis waarvan de premie tot stand is gekomen. Verzekeraars dekken zich tegen deze twee economische verschijnselen in via een premieopslag.
Kies uit:
bij (1) asymmetrische informatie / eigen risico / zelfbinding
bij (2) averechtse selectie / moral hazard
bij (3) averechtse selectie / moral hazard
bij (4) verwachte / werkelijke
bij (5) verwachte / werkelijke$$, array[]::uuid[]),
  ('4fddfaed-0dbf-4a8e-9993-958a0d815015', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 4,
   '[{"domain": "Risico en informatie", "subdomain": "Risico en verzekeren"}]'::jsonb,
   '["risico-aversie", "vraag naar verzekeringen", "positief verband", "pijlenschema"]'::jsonb,
   $$Uitleggen of risico-aversie positief of negatief samenhangt met de vraag naar schadepolissen.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag4.png$$, $$Gebruik bron 1, pijl 4.
2p 4 Heeft risicoaversie van consumenten een positief of een negatief effect op de vraag naar schadepolissen? Leg je keuze uit.$$, array['cdb2d960-05ad-4ef8-b851-a4a3b634b255', '6b07dcb9-9f1b-431a-895b-2f4d2371d289']::uuid[]),
  ('a63d7ea8-09ce-4654-a2f1-962dbd6e9941', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 5,
   '[{"domain": "Markt", "subdomain": "Marktvraag"}, {"domain": "Risico en informatie", "subdomain": "Risico en verzekeren"}]'::jsonb,
   '["verschuiving van de vraaglijn", "kans op schade", "collectieve vraaglijn", "verschuiving langs de vraaglijn"]'::jsonb,
   $$Kiezen welke grafiek de vraagverandering bij een grotere kans op schade juist weergeeft.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag5.png$$, $$Gebruik bron 1, pijl 2 en de grafieken uit bron 2.
2p 5 Welke grafiek geeft de vraagverandering bij een toename van de kans op schade juist weer? Leg je keuze uit.$$, array['6b07dcb9-9f1b-431a-895b-2f4d2371d289', 'a6a7ae3f-d859-4d56-a7fb-8e3d3e5c0633']::uuid[]),
  ('9d1d4cfc-8d0d-465d-81f3-d6232dc7e003', '004df4d5-e631-478e-87d2-8ce333c3b0ad', 6,
   '[{"domain": "Markt", "subdomain": "Marktmechanisme"}, {"domain": "Markt", "subdomain": "Marktvraag"}]'::jsonb,
   '["marginale kosten", "verschuiving aanbodlijn", "verschuiving van de vraaglijn", "schadelast", "nieuw marktevenwicht"]'::jsonb,
   $$Invullen hoe een hogere schadelast via aanbod- en vraagverschuivingen het aantal polissen beïnvloedt.$$,
   $$economie-havo-2022-ii-zonder-risico-geen-verzekering-vraag6.png$$, $$Gebruik bron 1, pijl 3.
3p 6 Maak van de redenering van de econoom een economisch juiste tekst.
Kies uit:
bij (1) af / toe
bij (2) naar links / naar rechts / niet
bij (3) verlagen / verhogen
bij (4) langs / van
bij (5) afnemen / toenemen
bij (6) naar links / naar rechts / niet
bij (7) negatief / positief$$, array['62066169-b532-42d3-9294-e44348934732', '6b07dcb9-9f1b-431a-895b-2f4d2371d289']::uuid[]),
  ('208e3800-cf1b-4c38-af09-7f8c07e2dacf', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', 7,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Gezinnen ruilen over de tijd"}]'::jsonb,
   '["roodstand", "consumptief krediet", "gemiddelde schuld berekenen", "lenen"]'::jsonb,
   $$Met de totale en gemiddelde roodstandschuld berekenen hoeveel volwassenen rood stonden.$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-vraag7.png$$, $$2p 7 Toon aan met een berekening dat de bewering van de onderzoeker juist is.$$, array['aed04d7e-17f9-41ee-aa73-6a28bd4bb8a8', '95ac0725-422c-47bc-af02-efc74a0628ca']::uuid[]),
  ('27c2e3a9-0f8f-48cb-b2ca-bb2b7d4670cf', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', 8,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Gezinnen ruilen over de tijd"}]'::jsonb,
   '["sparen", "rentestand", "consumentenvertrouwen", "inflatieverwachting"]'::jsonb,
   $$Invullen hoe rente, consumentenvertrouwen en inflatieverwachting de besparingen beïnvloeden.$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-vraag8.png$$, $$2p 8 Maak van onderstaande redenering een economisch juiste tekst:
Het bedrag aan besparingen hangt af van meerdere factoren: de rentestand, het consumentenvertrouwen en de hoogte van de inflatie.
− Bij een hoge rente zijn de besparingen …(1)… dan bij een lage rentestand.
− Bij een hoog consumentenvertrouwen zal ...(2)… worden gespaard dan bij een laag consumentenvertrouwen.
− Bij een hoge inflatieverwachting zal er …(3)... gespaard worden dan bij een lage inflatieverwachting, omdat de bestedingen worden ...(4)….
Kies uit:
bij (1) hoger / lager
bij (2) meer / minder
bij (3) meer / minder
bij (4) versneld / vertraagd$$, array[]::uuid[]),
  ('e6f4626b-493a-499c-b481-f5e5faee54d2', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', 9,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Gezinnen ruilen over de tijd"}]'::jsonb,
   '["passief sparen", "ruilen over de tijd", "uitstel van consumptie", "vermogen"]'::jsonb,
   $$Uitleggen of passief sparen (waardestijging van beleggingen) ruilen over de tijd is.$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-vraag9.png$$, $$1p 9 Leg uit of er bij passief sparen sprake is van ruilen over de tijd.$$, array['f492e54e-4703-4886-bce4-23ec50a6c838', '9c7f1326-08e5-41f2-b93d-1b85cd61ed83']::uuid[]),
  ('14349dcf-c0ab-4925-88ab-ad83c4d25ac0', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', 10,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Gezinnen ruilen over de tijd"}]'::jsonb,
   '["actief sparen", "passief sparen", "beleggingen", "vermogen"]'::jsonb,
   $$Situaties indelen als actief of passief sparen.$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-vraag10.png$$, $$2p 10 Geef voor elk van de onderstaande situaties aan of het actief sparen of passief sparen betreft.
(1) bedragen overmaken naar een spaarrekening
(2) koersverandering van aandelen
(3) aankoop van aandelen
(4) waardevermeerdering van de pensioenportefeuille$$, array['9c7f1326-08e5-41f2-b93d-1b85cd61ed83']::uuid[]),
  ('2dd249a1-edc7-4718-a02a-94af4290b9d6', '7399eb90-4f4c-4f4f-b226-d172f1c8ee8d', 11,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Gezinnen ruilen over de tijd"}]'::jsonb,
   '["spaarparadox", "actief sparen", "passief sparen", "levensloopplanning", "vermogen"]'::jsonb,
   $$Beredeneren hoe waardestijging van beleggingen en levensloopplanning de spaarparadox verklaren.$$,
   $$economie-havo-2022-ii-sparen-in-nederland-een-paradox-vraag11.png$$, $$3p 11 Beredeneer hoe de spaarparadox verklaard kan worden door een combinatie van factoren:
− de sterke waardestijging van de beleggingen;
− het spaargedrag van huishoudens in het kader van de levensloopplanning. Betrek in je redenering het onderscheid en de samenhang tussen actief en passief sparen.$$, array['f492e54e-4703-4886-bce4-23ec50a6c838', '9c7f1326-08e5-41f2-b93d-1b85cd61ed83', '13139fcc-6e3b-4eaf-935e-8d76e57979e8']::uuid[]),
  ('2723e89b-dead-411f-bdc9-60f809a7195a', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', 12,
   '[{"domain": "Markt", "subdomain": "Kostenstructuur en opbrengsten"}]'::jsonb,
   '["gemiddelde totale kosten", "constante kosten", "schaalvoordelen", "online verkoop"]'::jsonb,
   $$Uitleggen waarom online reisbureaus lagere gemiddelde totale kosten hebben.$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-vraag12.png$$, $$1p 12 Leg uit waarom de online reisbureaus lagere gemiddelde totale kosten (GTK) hebben dan reisbureaus met een fysieke winkel.$$, array['a86fb107-5d4e-43b4-8579-573390f87509']::uuid[]),
  ('fce2a236-0833-4702-874f-480b34499d03', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', 13,
   '[{"domain": "Markt", "subdomain": "Marktmechanisme"}, {"domain": "Markt", "subdomain": "Producentengedrag"}]'::jsonb,
   '["marktevenwicht", "toetreding", "aanbodlijn", "gemiddelde winst"]'::jsonb,
   $$Met het marktevenwicht uitleggen hoe toetreding van aanbieders de gemiddelde winst verlaagt.$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-vraag13.png$$, $$2p 13 Leg met behulp van het marktevenwicht uit waarom de gemiddelde winst voor alle reisbureaus is gedaald door de toename van online reisbureaus.$$, array['a86fb107-5d4e-43b4-8579-573390f87509']::uuid[]),
  ('e773c0de-ecae-4465-878d-5a77c179dfde', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', 14,
   '[{"domain": "Markt", "subdomain": "Kostenstructuur en opbrengsten"}, {"domain": "Markt", "subdomain": "Producentengedrag"}]'::jsonb,
   '["gemiddelde totale kosten", "toetreding", "prijsconcurrentie", "gemiddelde winst"]'::jsonb,
   $$Uitleggen hoe lagere gemiddelde kosten van toetreders via lagere prijzen de winst van alle aanbieders verlagen.$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-vraag14.png$$, $$3p 14 Leg uit hoe de toetreding van online reisbureaus via lagere gemiddelde totale kosten (GTK) uiteindelijk kon leiden tot lagere gemiddelde winst voor alle reisbureaus.$$, array['a86fb107-5d4e-43b4-8579-573390f87509', '907260bd-98e5-4a92-854f-75d441f5a117']::uuid[]),
  ('9006d2f3-2b93-407f-b90c-9fd1974c4a1b', 'd6a64ab0-6cf6-491d-ac9e-6a1375714df4', 15,
   '[{"domain": "Markt", "subdomain": "Consumentengedrag"}]'::jsonb,
   '["prijselasticiteit van de vraag", "elastische vraag", "inelastische vraag", "omzet"]'::jsonb,
   $$Met prijselasticiteiten beoordelen of uitspraken over afzetgroei en omzetverandering juist zijn.$$,
   $$economie-havo-2022-ii-de-reisbranche-in-zwaar-weer-vraag15.png$$, $$Gebruik bron 1.
3p 15 Leg voor elk van de uitspraken 1 en 2 uit of ze juist of onjuist zijn. Betrek de prijselasticiteiten in je uitleg.$$, array['e0e313a2-d272-4ca1-a9af-423f435fe7a5', 'c1004188-685f-4d14-8637-33e00bc9985a']::uuid[]),
  ('eb0a52c9-0682-46b8-946e-4dbb0fbb6605', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', 16,
   '[{"domain": "Markt", "subdomain": "Marktvormen"}]'::jsonb,
   '["monopolistische concurrentie", "heterogeen product", "marktkenmerken", "prijszetter"]'::jsonb,
   $$Een kenmerk van monopolistische concurrentie noemen en toepassen op de kamermarkt.$$,
   $$economie-havo-2022-ii-kamertje-verhuren-vraag16.png$$, $$1p 16 Noem een kenmerk van monopolistische concurrentie en laat met een voorbeeld zien dat dit kenmerk van toepassing is op de markt van studentenkamers in Amsterdam.$$, array['070b289f-45e4-47c5-ba9d-91df1cf40e8c']::uuid[]),
  ('39adf09f-6ac6-4a39-afc5-a3f606277aec', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', 17,
   '[{"domain": "Markt", "subdomain": "Markt falen, overheidsingrijpen en welvaart"}]'::jsonb,
   '["collectieve goederen", "uitsluitbaarheid", "rivaliteit", "quasi-collectieve goederen"]'::jsonb,
   $$Met de twee kenmerken van collectieve goederen uitleggen dat gemeentelijke studentenkamers geen collectief goed zijn.$$,
   $$economie-havo-2022-ii-kamertje-verhuren-vraag17.png$$, $$2p 17 Leg uit dat studentenkamers die door de gemeente worden gebouwd geen collectieve goederen zijn. Betrek de twee kenmerken van collectieve goederen in je antwoord.$$, array['56764ada-1948-41ac-8079-7cd866372b4c', 'cda28dea-00a7-49ee-a05c-b35bd27d0e2b']::uuid[]),
  ('0de6ce08-0f84-4522-8b3a-4b051fc56fc6', 'acaf0d33-05c9-421a-ba6e-c3595c773de6', 18,
